payload.text:
Saya akan melakukan perbaikan pada **AttendanceRecapPage** (Rekap Kehadiran) dan **AttendanceDetailModal** untuk memastikan sinkronisasi data yang akurat antara Admin dan Siswa.

Masalah utamanya kemungkinan besar terletak pada perbedaan cara sistem menghasilkan "Kunci Tanggal" (Date Key) dan "Nama Hari" antara halaman Admin (saat input) dan halaman Rekap (saat membaca). Perbedaan zona waktu sering menyebabkan tanggal bergeser 1 hari, sehingga data "Hadir" di Admin terbaca sebagai "Pending/Kosong" di halaman Siswa.

Berikut adalah spesifikasi perbaikannya:

1.  **Standardisasi Format Tanggal (`dateKey`):** Saya akan mengubah logika di halaman rekap agar menyusun tanggal secara manual (format `YYYY-MM-DD`) alih-alih mengandalkan fungsi `toISOString()` bawaan browser yang terpengaruh zona waktu. Ini menjamin bahwa tanggal "20 Oktober" di Admin pasti terbaca sebagai "20 Oktober" di halaman Siswa.
2.  **Standardisasi Nama Hari:** Memastikan perhitungan nama hari (Senin, Selasa, dst.) menggunakan indeks array yang baku, sama persis dengan logika di Admin, sehingga ID Sesi (`sessionId`) yang dihasilkan identik.

Berikut adalah kode yang diperbarui:

# Updated files:

## components/AttendanceRecapPage.tsx

```tsx
import React, { useState, useMemo } from 'react';
import { Child, AttendanceStatus } from '../types';
import AttendanceDetailModal from './AttendanceDetailModal';

type MasterChild = Omit<Child, 'sessions'>;

interface AttendanceRecapPageProps {
  allChildren: MasterChild[];
  attendanceRecords: { [dateKey: string]: { [sessionId: string]: AttendanceStatus } };
}

export interface RecapData {
  childId: string;
  childName: string;
  photoUrl: string;
  totalSessions: number;
  present: number;
  absent: number;
  pending: number;
  attendanceRate: number;
}

type SortableKeys = keyof RecapData;

// Must match the array used in App.tsx for ID generation consistency
const daysOfWeek = ["Senin", "Selasa", "Rabu", "Kamis", "Jumat", "Sabtu", "Minggu"];

const AttendanceRecapPage: React.FC<AttendanceRecapPageProps> = ({ allChildren, attendanceRecords }) => {
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().substring(0, 7));
  const [sortConfig, setSortConfig] = useState<{ key: SortableKeys; direction: 'ascending' | 'descending' } | null>({ key: 'childName', direction: 'ascending' });
  const [selectedChild, setSelectedChild] = useState<RecapData | null>(null);

  const monthlyRecapData = useMemo<RecapData[]>(() => {
    if (!allChildren) return [];

    const [year, month] = selectedDate.split('-').map(Number);
    const daysInMonth = new Date(year, month, 0).getDate();

    return allChildren.map(child => {
      let totalSessions = 0;
      let present = 0;
      let absent = 0;
      let pending = 0;

      if (child.recurringSessions) {
        for (let day = 1; day <= daysInMonth; day++) {
            const date = new Date(year, month - 1, day);

            // Deterministic day mapping to ensure ID match with Admin input
            const dayIndex = date.getDay(); // 0 is Sunday
            const dayOfWeekName = daysOfWeek[dayIndex === 0 ? 6 : dayIndex - 1];

            // USE MANUAL STRING CONSTRUCTION TO AVOID TIMEZONE SHIFTS
            // This ensures "2023-10-20" matches exactly what Admin saved, regardless of browser timezone.
            const dateKey = `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;

            const sessionsOnThisDay = child.recurringSessions.filter(rs => rs.day === dayOfWeekName);
            totalSessions += sessionsOnThisDay.length;

            sessionsOnThisDay.forEach(recSession => {
                // Ensure this ID construction matches App.tsx EXACTLY
                const sessionId = `s-recur-${child.id}-${dayOfWeekName.replace(/\s/g, '')}-${recSession.time}`;
                const status = attendanceRecords[dateKey]?.[sessionId] || AttendanceStatus.PENDING;
                switch(status) {
                    case AttendanceStatus.PRESENT: present++; break;
                    case AttendanceStatus.ABSENT: absent++; break;
                    case AttendanceStatus.PENDING: pending++; break;
                }
            });
        }
      }

      const totalAttended = present + absent;
      const attendanceRate = totalAttended > 0 ? (present / totalAttended) * 100 : 0;

      return {
        childId: child.id,
        childName: child.name,
        photoUrl: child.photoUrl,
        totalSessions,
        present,
        absent,
        pending,
        attendanceRate: parseFloat(attendanceRate.toFixed(1)),
      };
    });
  }, [allChildren, attendanceRecords, selectedDate]);

  const sortedRecapData = useMemo(() => {
    let sortableItems = [...monthlyRecapData];
    if (sortConfig !== null) {
      sortableItems.sort((a, b) => {
        if (a[sortConfig.key] < b[sortConfig.key]) {
          return sortConfig.direction === 'ascending' ? -1 : 1;
        }
        if (a[sortConfig.key] > b[sortConfig.key]) {
          return sortConfig.direction === 'ascending' ? 1 : -1;
        }
        return 0;
      });
    }
    return sortableItems;
  }, [monthlyRecapData, sortConfig]);

  const requestSort = (key: SortableKeys) => {
    let direction: 'ascending' | 'descending' = 'ascending';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'ascending') {
      direction = 'descending';
    }
    setSortConfig({ key, direction });
  };

  const getSortIndicator = (key: SortableKeys) => {
    if (!sortConfig || sortConfig.key !== key) return null;
    return sortConfig.direction === 'ascending' ? '▲' : '▼';
  };

  return (
    <>
      <AttendanceDetailModal
        isOpen={!!selectedChild}
        onClose={() => setSelectedChild(null)}
        childData={selectedChild}
        allChildren={allChildren}
        attendanceRecords={attendanceRecords}
        selectedMonth={selectedDate}
      />
      <main className="p-8">
        <div className="max-w-6xl mx-auto">
          <div className="flex justify-between items-center mb-6 flex-wrap gap-4">
              <div>
                  <h1 className="text-2xl font-bold text-white">Rekap Kehadiran Bulanan</h1>
                  <p className="text-sm text-muted mt-1">Menampilkan ringkasan kehadiran siswa untuk bulan yang dipilih.</p>
              </div>
              <div className="flex items-center gap-2">
                  <label htmlFor="month-picker" className="text-sm font-medium text-muted">Pilih Bulan:</label>
                  <input
                      type="month"
                      id="month-picker"
                      value={selectedDate}
                      onChange={(e) => setSelectedDate(e.target.value)}
                      className="bg-surface-light border border-surface-light/50 text-white placeholder-muted text-sm rounded-lg focus:ring-primary focus:border-primary p-2 transition"
                  />
              </div>
          </div>

          <div className="bg-surface border border-surface-light rounded-2xl shadow-lg overflow-hidden">
            <div className="overflow-x-auto">
              <table className="min-w-full divide-y divide-surface-light">
                <thead className="bg-background/50">
                  <tr>
                    {([
                      { key: 'childName', label: 'Nama Siswa' },
                      { key: 'totalSessions', label: 'Total Sesi' },
                      { key: 'present', label: 'Hadir' },
                      { key: 'absent', label: 'Absen' },
                      { key: 'attendanceRate', label: 'Tingkat Kehadiran (%)' },
                    ] as { key: SortableKeys, label: string }[]).map(({ key, label }) => (
                       <th key={key} scope="col" className="px-6 py-4 text-left text-xs font-medium text-muted uppercase tracking-wider cursor-pointer hover:text-white" onClick={() => requestSort(key)}>
                          {label} {getSortIndicator(key)}
                       </th>
                    ))}
                  </tr>
                </thead>
                <tbody className="bg-surface divide-y divide-surface-light">
                  {sortedRecapData.map((data) => (
                    <tr key={data.childId} className="hover:bg-surface-light/50 transition-colors">
                      <td className="px-6 py-4 whitespace-nowrap">
                          <button onClick={() => setSelectedChild(data)} className="flex items-center text-left hover:opacity-80 transition-opacity w-full group">
                              <img className="h-10 w-10 rounded-full object-cover ring-2 ring-surface-light group-hover:ring-primary transition" src={data.photoUrl} alt={data.childName} />
                              <div className="ml-4">
                                  <div className="text-sm font-medium text-white">{data.childName}</div>
                                  <div className="text-xs text-muted font-mono">{data.childId}</div>
                              </div>
                          </button>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-left text-sm font-bold text-white">{data.totalSessions}</td>
                      <td className="px-6 py-4 whitespace-nowrap text-left text-sm text-success">{data.present}</td>
                      <td className="px-6 py-4 whitespace-nowrap text-left text-sm text-danger">{data.absent}</td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-white text-left">
                        <div className="flex items-center gap-2">
                          <div className="w-full bg-surface-light rounded-full h-2.5">
                              <div className="bg-primary h-2.5 rounded-full" style={{ width: `${data.attendanceRate}%` }}></div>
                          </div>
                          <span className="font-semibold w-12 text-right">{data.attendanceRate}%</span>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </main>
    </>
  );
};

export default AttendanceRecapPage;
```

## components/AttendanceDetailModal.tsx

```tsx
import React, { useMemo, useState, useEffect } from 'react';
import { Child, AttendanceStatus } from '../types';
import { RecapData } from './AttendanceRecapPage';

type MasterChild = Omit<Child, 'sessions'>;

interface AttendanceDetailModalProps {
  isOpen: boolean;
  onClose: () => void;
  childData: RecapData | null;
  allChildren: MasterChild[];
  attendanceRecords: { [dateKey: string]: { [sessionId: string]: AttendanceStatus } };
  selectedMonth: string; // YYYY-MM
}

const statusStyles: { [key in AttendanceStatus]: { bg: string; text: string } } = {
  [AttendanceStatus.PRESENT]: { bg: 'bg-success/80', text: 'text-white' },
  [AttendanceStatus.ABSENT]: { bg: 'bg-danger/80', text: 'text-white' },
  [AttendanceStatus.PENDING]: { bg: 'bg-warning/80', text: 'text-black' },
};

const LegendItem: React.FC<{ colorClass: string, label: string }> = ({ colorClass, label }) => (
    <div className="flex items-center gap-2">
        <div className={`w-4 h-4 rounded ${colorClass}`}></div>
        <span className="text-xs text-muted">{label}</span>
    </div>
);

// Must match App.tsx
const daysOfWeek = ["Senin", "Selasa", "Rabu", "Kamis", "Jumat", "Sabtu", "Minggu"];

const AttendanceDetailModal: React.FC<AttendanceDetailModalProps> = ({ isOpen, onClose, childData, allChildren, attendanceRecords, selectedMonth }) => {
  const [currentMonth, setCurrentMonth] = useState(selectedMonth);

  useEffect(() => {
    if (isOpen) {
      setCurrentMonth(selectedMonth);
    }
  }, [isOpen, selectedMonth]);

  const childMasterData = useMemo(() => {
      if (!childData) return null;
      return allChildren.find(c => c.id === childData.childId);
  }, [childData, allChildren]);

  const recalculatedStats = useMemo(() => {
    if (!childData || !childMasterData?.recurringSessions) return { totalSessions: 0, present: 0, absent: 0, pending: 0 };

    const [year, month] = currentMonth.split('-').map(Number);
    const daysInMonth = new Date(year, month, 0).getDate();

    let totalSessions = 0;
    let present = 0;
    let absent = 0;
    let pending = 0;

    for (let day = 1; day <= daysInMonth; day++) {
        const date = new Date(year, month - 1, day);

        // Deterministic day mapping
        const dayIndex = date.getDay(); 
        const dayOfWeekName = daysOfWeek[dayIndex === 0 ? 6 : dayIndex - 1];

        // USE MANUAL STRING CONSTRUCTION TO AVOID TIMEZONE SHIFTS
        const dateKey = `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;

        const sessionsOnThisDay = childMasterData.recurringSessions.filter(rs => rs.day === dayOfWeekName);
        totalSessions += sessionsOnThisDay.length;

        sessionsOnThisDay.forEach(recSession => {
            const sessionId = `s-recur-${childData.childId}-${dayOfWeekName.replace(/\s/g, '')}-${recSession.time}`;
            const status = attendanceRecords[dateKey]?.[sessionId] || AttendanceStatus.PENDING;
            switch(status) {
                case AttendanceStatus.PRESENT: present++; break;
                case AttendanceStatus.ABSENT: absent++; break;
                case AttendanceStatus.PENDING: pending++; break;
            }
        });
    }
    return { totalSessions, present, absent, pending };

  }, [currentMonth, childData, childMasterData, attendanceRecords]);


  const calendarData = useMemo(() => {
    if (!childData) return { blanks: [], days: [] };

    const [year, month] = currentMonth.split('-').map(Number);
    const date = new Date(year, month - 1, 1);

    const firstDayOfMonth = date.getDay();
    const startDay = firstDayOfMonth === 0 ? 6 : firstDayOfMonth - 1;

    const daysInMonth = new Date(year, month, 0).getDate();

    const blanks = Array(startDay).fill(null);
    const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);

    return { blanks, days };
  }, [currentMonth, childData]);

  if (!isOpen || !childData) return null;

  const getStatusForDay = (day: number): AttendanceStatus | null => {
    const [year, month] = currentMonth.split('-').map(Number);
    const date = new Date(year, month - 1, day);

    // Deterministic day mapping
    const dayIndex = date.getDay(); 
    const dayOfWeekName = daysOfWeek[dayIndex === 0 ? 6 : dayIndex - 1];

    // USE MANUAL STRING CONSTRUCTION TO AVOID TIMEZONE SHIFTS
    const dateKey = `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;

    if (!childMasterData?.recurringSessions) return null;

    const sessionsOnThisDay = childMasterData.recurringSessions.filter(rs => rs.day === dayOfWeekName);
    if (sessionsOnThisDay.length === 0) return null;

    // Simplification: Show status of the first session of the day on the calendar.
    // If there are multiple sessions, logic can be expanded, but usually looking for any 'PRESENT' or 'ABSENT'.
    const firstSession = sessionsOnThisDay.sort((a,b) => a.time.localeCompare(b.time))[0];
    const sessionId = `s-recur-${childData.childId}-${dayOfWeekName.replace(/\s/g, '')}-${firstSession.time}`;
    return attendanceRecords[dateKey]?.[sessionId] || AttendanceStatus.PENDING;
  };

  const weekdays = ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min'];

  return (
    <div className="fixed inset-0 bg-background/80 backdrop-blur-sm z-50 flex items-center justify-center animate-fade-in-up" onClick={onClose}>
      <div className="bg-surface border border-surface-light rounded-2xl shadow-xl w-full max-w-2xl m-4" onClick={e => e.stopPropagation()}>
        <div className="p-6 border-b border-surface-light flex justify-between items-center flex-wrap gap-4">
            <div className="flex items-center gap-4">
                <img src={childData.photoUrl} alt={childData.childName} className="h-12 w-12 rounded-full object-cover ring-2 ring-primary"/>
                <div>
                    <h3 className="text-lg font-semibold text-white">Detail Kehadiran</h3>
                    <p className="text-sm text-muted">{childData.childName}</p>
                </div>
            </div>
            <div className="flex items-center gap-2">
                 <input
                      type="month"
                      id="month-picker-modal"
                      value={currentMonth}
                      onChange={(e) => setCurrentMonth(e.target.value)}
                      className="bg-surface-light border border-surface-light/50 text-white placeholder-muted text-sm rounded-lg focus:ring-primary focus:border-primary p-2 transition"
                  />
                <button onClick={onClose} className="text-muted hover:text-white transition-colors">
                    <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                </button>
            </div>
        </div>
        <div className="p-6">
            <div className="grid grid-cols-4 gap-4 mb-6 text-center bg-surface-light p-4 rounded-lg">
                <div><p className="text-xs text-muted">Total Sesi</p><p className="text-xl font-bold text-white">{recalculatedStats.totalSessions}</p></div>
                <div><p className="text-xs text-muted">Hadir</p><p className="text-xl font-bold text-success">{recalculatedStats.present}</p></div>
                <div><p className="text-xs text-muted">Absen</p><p className="text-xl font-bold text-danger">{recalculatedStats.absent}</p></div>
                <div><p className="text-xs text-muted">Menunggu</p><p className="text-xl font-bold text-warning">{recalculatedStats.pending}</p></div>
            </div>

            <div className="grid grid-cols-7 gap-2 text-center text-xs font-bold text-muted mb-2">
                {weekdays.map(day => <div key={day}>{day}</div>)}
            </div>

            <div className="grid grid-cols-7 gap-2">
              {calendarData.blanks.map((_, index) => <div key={`blank-${index}`} className="w-full aspect-square"></div>)}
              {calendarData.days.map(day => {
                const status = getStatusForDay(day);
                const style = status ? statusStyles[status] : { bg: 'bg-surface-light/50', text: 'text-slate-400' };

                return (
                  <div key={day} className={`w-full aspect-square flex items-center justify-center rounded-lg font-semibold ${style.bg} ${style.text}`}>
                    {day}
                  </div>
                );
              })}
            </div>

             <div className="flex justify-center items-center gap-4 mt-6 border-t border-surface-light pt-4">
                <LegendItem colorClass="bg-success" label="Hadir" />
                <LegendItem colorClass="bg-danger" label="Absen" />
                <LegendItem colorClass="bg-warning" label="Menunggu" />
                <LegendItem colorClass="bg-surface-light" label="Tanpa Sesi" />
            </div>
        </div>
      </div>
    </div>
  );
};

export default AttendanceDetailModal;

