import React from 'react';

export type View = 'dashboard' | 'manajemenAnak' | 'assesmentAnak' | 'manajemenTerapis' | 'laporanPerkembangan' | 'laporanKeuangan' | 'laporanPemasukan' | 'tagihan' | 'tinjauanMingguan' | 'laporanAssesment' | 'pengaturan' | 'manajemenPengguna' | 'rekapKehadiran' | 'balancedScorecard' | 'strategicPlan';

export type UserRole = 'admin' | 'siswa' | 'terapis' | null;

export interface MenuItem {
  id: View;
  label: string;
  Icon: React.FC<{ className?: string }>;
  group: number;
}

export interface HeaderMenuItem {
  id: string;
  label: string;
  href: string;
  isExternal?: boolean;
}

export enum AttendanceStatus {
  PRESENT = 'Hadir',
  ABSENT = 'Absen',
  PENDING = 'Menunggu',
}

export enum AssessmentStatus {
  NOT_ASSESSED = 'Belum Dinilai',
  IN_PROGRESS = 'Proses',
  COMPLETED = 'Selesai',
}

export interface TherapyDefinition {
  id: string;
  name: string;
  Icon: React.FC<{ className?: string }>;
  color: string;
}

export interface TherapySession {
  id: string;
  type: string; 
  therapistId: string; // Changed from therapist: string
  time: string;
  status: AttendanceStatus;
}

export interface RecurringSession {
  day: string;
  time: string;
  type: string; 
  therapistId?: string;
