import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Child, RecurringSession, TherapyDefinition, Therapist, AssessmentStatus, UserRole, TherapySession } from '../types';
import UploadChildDataModal from './UploadChildDataModal';
import UploadIcon from './icons/UploadIcon';


type MasterChild = Omit<Child, 'sessions'>;

interface DeactivateModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (reason: string) => void;
  child: MasterChild | null;
}

const DeactivateModal: React.FC<DeactivateModalProps> = ({ isOpen, onClose, onConfirm, child }) => {
    const [reason, setReason] = useState('');

    if (!isOpen || !child) return null;

    const handleConfirm = () => {
        if (!reason.trim()) {
            alert('Silakan masukkan alasan penonaktifan.');
            return;
        }
        onConfirm(reason);
        setReason('');
    };

    return (
        <div className="fixed inset-0 bg-background/80 backdrop-blur-sm z-[60] flex items-center justify-center animate-fade-in-up">
            <div className="bg-surface border border-surface-light rounded-2xl shadow-xl w-full max-w-md m-4">
                <div className="p-6 border-b border-surface-light">
                    <h3 className="text-lg font-semibold text-white">Konfirmasi Penonaktifan</h3>
                    <p className="text-sm text-muted">Anda akan menonaktifkan siswa: <span className="text-white font-bold">{child.name}</span></p>
                </div>
                <div className="p-6 space-y-4">
                    <div>
                        <label className="block mb-2 text-xs font-medium text-muted">Alasan Tidak Aktif</label>
                        <textarea 
                            value={reason} 
                            onChange={e => setReason(e.target.value)} 
                            className="bg-background border border-surface-light/50 text-white text-sm rounded-lg focus:ring-primary focus:border-primary block w-full p-2.5"
                            placeholder="Contoh: Lulus, Pindah Sekolah, Mengundurkan Diri..."
                            rows={3}
                        />
                    </div>
                </div>
                <div className="px-6 py-4 bg-background/50 rounded-b-2xl flex justify-end gap-3">
                    <button onClick={onClose} className="px-4 py-2 text-sm font-medium text-muted bg-surface-light rounded-lg hover:bg-surface-light/50 transition">Batal</button>
                    <button onClick={handleConfirm} className="px-4 py-2 text-sm font-medium text-white bg-danger rounded-lg hover:bg-danger/80 transition">Nonaktifkan Siswa</button>
                </div>
            </div>
        </div>
    );
};

interface AddDailySessionModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (session: Omit<TherapySession, 'id' | 'status'>, date: string) => void;
  child: MasterChild | null;
  therapyTypes: TherapyDefinition[];
  therapyTimes: string[];
  therapists: Therapist[];
}

const AddDailySessionModal: React.FC<AddDailySessionModalProps> = ({ isOpen, onClose, onSave, child, therapyTypes, therapyTimes, therapists }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [time, setTime] = useState(therapyTimes[0]);
  const [type, setType] = useState(therapyTypes[0]?.id || '');
  const [therapistId, setTherapistId] = useState(therapists[0]?.id || '');

  useEffect(() => {
    if (therapyTypes.length > 0 && !type) {
        setType(therapyTypes[0].id);
    }
    if (therapists.length > 0 && !therapistId) {
        setTherapistId(therapists[0].id);
    }
  }, [therapyTypes, therapists, type, therapistId]);

  if (!isOpen || !child) return null;

  const handleSave = () => {
    if (!type || !time || !therapistId || !date) {
        alert('Semua kolom harus diisi.');
        return;
    }
    onSave({ type, time, therapistId }, date);
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-background/80 backdrop-blur-sm z-50 flex items-center justify-center animate-fade-in-up">
      <div className="bg-surface border border-surface-light rounded-2xl shadow-xl w-full max-w-md m-4">
        <div className="p-6 border-b border-surface-light flex justify-between items-center">
            <div>
              <h3 className="text-lg font-semibold text-white">Tambah Sesi Harian</h3>
              <p className="text-sm text-muted">{child.name}</p>
            </div>
          <button onClick={onClose} className="text-muted hover:text-white transition-colors">
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
          </button>
        </div>
        <div className="p-6 space-y-4">
            <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="block mb-2 text-xs font-medium text-muted">Tanggal</label>
                    <input type="date" value={date} onChange={e => setDate(e.target.value)} className="bg-background border border-surface-light/50 text-white text-sm rounded-lg focus:ring-primary focus:border-primary block w-full p-2.5"/>
                </div>
                <div>
                    <label className="block mb-2 text-xs font-medium text-muted">Jam</label>
                    <select value={time} onChange={e => setTime(e.target.value)} className="bg-background border border-surface-light/50 text-white text-sm rounded-lg focus:ring-primary focus:border-primary block w-full p-2.5">
                        {therapyTimes.map(t => <option key={t} value={t}>{t}</option>)}
                    </select>
                </div>
            </div>
            <div>
                <label className="block mb-2 text-xs font-medium text-muted">Jenis Terapi</label>
                <select value={type} onChange={e => setType(e.target.value)} className="bg-background border border-surface-light/50 text-white text-sm rounded-lg focus:ring-primary focus:border-primary block w-full p-2.5">
                    {therapyTypes.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
                </select>
            </div>
            <div>
                <label className="block mb-2 text-xs font-medium text-muted">Terapis</label>
                <select value={therapistId} onChange={e => setTherapistId(e.target.value)} className="bg-background border border-surface-light/50 text-white text-sm rounded-lg focus:ring-primary focus:border-primary block w-full p-2.5">
                    {therapists.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
                </select>
            </div>
        </div>
        <div className="px-6 py-4 bg-background/50 rounded-b-2xl flex justify-end gap-3">
          <button onClick={onClose} className="px-4 py-2 text-sm font-medium text-muted bg-surface-light rounded-lg hover:bg-surface-light/50 transition">Batal</button>
          <button onClick={handleSave} className="px-4 py-2 text-sm font-medium text-background bg-primary rounded-lg hover:bg-primary-dark transition">Simpan Sesi</button>
        </div>
      </div>
    </div>
  );
};


interface ChildManagementPageProps {
  children: MasterChild[];
  onAddChild: (name: string) => void;
  onAddMultipleChildren: (newChildren: Omit<MasterChild, 'id'>[]) => void;
  onUpdateChild: (childId: string, updates: Partial<Omit<MasterChild, 'id'>>) => void;
  onDeleteChild: (childId: string) => void;
  onAddDailySession: (childId: string, session: Omit<TherapySession, 'id' | 'status'>, date: string) => void;
  therapyTypes: TherapyDefinition[];
  therapyTimes: string[];
  daysOfWeek: string[];
  therapists: Therapist[];
  userRole: UserRole;
}

const EditChildModal: React.FC<{
  isOpen: boolean;
  child: MasterChild | null;
  onClose: () => void;
  onSave: (updates: Partial<Omit<MasterChild, 'id'>>) => void;
  therapyTypes: TherapyDefinition[];
  therapyTimes: string[];
  daysOfWeek: string[];
  therapists: Therapist[];
}> = ({ isOpen, child, onClose, onSave, therapyTypes, therapyTimes, daysOfWeek, therapists }) => {
  const [name, setName] = useState('');
  const [photoUrl, setPhotoUrl] = useState('');
  const [sessions, setSessions] = useState<RecurringSession[]>([]);

  const [newSessionDay, setNewSessionDay] = useState<string>(daysOfWeek[0]);
  const [newSessionTime, setNewSessionTime] = useState<string>(therapyTimes[0]);
  const [newSessionType, setNewSessionType] = useState<string>(therapyTypes[0]?.id || '');
  const [newSessionTherapist, setNewSessionTherapist] = useState<string>('any');

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (child) {
      setName(child.name);
      setPhotoUrl(child.photoUrl);
      setSessions(child.recurringSessions || []);
    }
  }, [child]);

  useEffect(() => {
    if (therapyTypes.length > 0 && !newSessionType) {
        setNewSessionType(therapyTypes[0].id);
    }
  }, [therapyTypes, newSessionType]);


  if (!isOpen || !child) return null;

  const handlePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        if (typeof reader.result === 'string') {
          setPhotoUrl(reader.result);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const triggerFileInput = () => {
    fileInputRef.current?.click();
  };

  const handleAddSession = () => {
    if (!newSessionType) {
        alert('Silakan pilih jenis terapi.');
        return;
    }
    const newSession: RecurringSession = {
        day: newSessionDay,
        time: newSessionTime,
        type: newSessionType,
        therapistId: newSessionTherapist === 'any' ? undefined : newSessionTherapist,
    };
    if (!sessions.some(s => s.day === newSession.day && s.time === newSession.time)) {
        setSessions([...sessions, newSession]);
    } else {
        alert('Sesi pada hari dan jam ini sudah ada.');
    }
  };

  const handleRemoveSession = (index: number) => {
    setSessions(sessions.filter((_, i) => i !== index));
  }

  const handleSave = () => {
    onSave({ name, photoUrl, recurringSessions: sessions });
  }

  return (
    <div className="fixed inset-0 bg-background/80 backdrop-blur-sm z-50 flex items-center justify-center animate-fade-in-up">
      <div className="bg-surface border border-surface-light rounded-2xl shadow-xl w-full max-w-3xl m-4">
        <div className="p-6 border-b border-surface-light flex justify-between items-center">
          <h3 className="text-lg font-semibold text-white">Edit Data Siswa</h3>
          <button onClick={onClose} className="text-muted hover:text-white transition-colors">
             <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
          </button>
        </div>
        <div className="p-6 max-h-[70vh] overflow-y-auto grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Left side: Profile */}
            <div className="space-y-4">
                <h4 className="text-md font-semibold text-white mb-2">Profil Siswa</h4>
                 <div>
                    <label className="block mb-2 text-xs font-medium text-muted">Nama Lengkap</label>
                    <input type="text" value={name} onChange={(e) => setName(e.target.value)} className="bg-background border border-surface-light/50 text-white text-sm rounded-lg focus:ring-primary focus:border-primary block w-full p-2.5"/>
                </div>
                <div>
                    <label className="block mb-2 text-xs font-medium text-muted">Foto Profil</label>
                    <div className="mt-2 flex justify-center">
                        <div className="relative group">
                            <img
                                src={photoUrl}
                                alt="Preview"
                                className="h-24 w-24 rounded-full object-cover ring-2 ring-primary/50 cursor-pointer transition-opacity group-hover:opacity-70"
                            />
                            <button
                                type="button"
                                onClick={triggerFileInput}
                                className="absolute inset-0 flex items-center justify-center bg-black/50 rounded-full opacity-0 group-hover:opacity-100 transition-opacity"
                                aria-label="Ganti foto"
                            >
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                                <span className="sr-only">Ganti Foto</span>
                            </button>
                        </div>
                        <input
                            ref={fileInputRef}
                            type="file"
                            accept="image/*"
                            onChange={handlePhotoChange}
                            className="hidden"
                        />
                    </div>
                </div>
            </div>

            {/* Right side: Schedule */}
            <div>
                 <div className="bg-surface-light p-4 rounded-lg mb-6">
                    <h4 className="text-md font-semibold text-white mb-3">Tambah Sesi Rutin</h4>
                    <div className="grid grid-cols-1 gap-4 items-end">
                        <div className="grid grid-cols-3 gap-2">
                            <select value={newSessionType} onChange={(e) => setNewSessionType(e.target.value)} className="bg-background border border-surface-light/50 text-white text-sm rounded-lg focus:ring-primary focus:border-primary block w-full p-2.5">
                                {therapyTypes.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
                            </select>
                            <select value={newSessionDay} onChange={(e) => setNewSessionDay(e.target.value)} className="bg-background border border-surface-light/50 text-white text-sm rounded-lg focus:ring-primary focus:border-primary block w-full p-2.5">
                                {daysOfWeek.map(d => <option key={d} value={d}>{d}</option>)}
                            </select>
                            <select value={newSessionTime} onChange={(e) => setNewSessionTime(e.target.value)} className="bg-background border border-surface-light/50 text-white text-sm rounded-lg focus:ring-primary focus:border-primary block w-full p-2.5">
                                {therapyTimes.map(t => <option key={t} value={t}>{t}</option>)}
                            </select>
                        </div>
                        <div>
                            <label className="block mb-1 text-xs font-medium text-muted">Terapis (Opsional)</label>
                            <select value={newSessionTherapist} onChange={(e) => setNewSessionTherapist(e.target.value)} className="bg-background border border-surface-light/50 text-white text-sm rounded-lg focus:ring-primary focus:border-primary block w-full p-2.5">
                                <option value="any">Terapis Acak (Sesuai Spesialisasi)</option>
                                {therapists.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
                            </select>
                        </div>
                        <div>
                            <button onClick={handleAddSession} className="w-full bg-secondary hover:bg-secondary/80 text-white font-bold py-2.5 px-4 rounded-lg transition">Tambah Sesi</button>
                        </div>
                    </div>
                </div>

                <h4 className="text-md font-semibold text-white mb-3">Daftar Sesi Rutin ({sessions.length})</h4>
                <div className="space-y-2 max-h-52 overflow-y-auto pr-2">
                    {sessions.length > 0 ? sessions.sort((a,b) => daysOfWeek.indexOf(a.day) - daysOfWeek.indexOf(b.day) || a.time.localeCompare(b.time)).map((session, index) => {
                        const therapist = therapists.find(t => t.id === session.therapistId);
                        return (
                          <div key={index} className="flex justify-between items-center bg-surface-light/50 p-3 rounded-lg animate-fade-in-up">
                             <div className="flex items-center gap-4 text-sm flex-1 min-w-0">
                                  <span className="font-semibold text-primary w-20">{session.day}</span>
                                  <span className="font-mono text-white bg-background/50 px-2 py-0.5 rounded">{session.time}</span>
                                  <div className="flex-1 truncate">
                                      <p className="text-slate-300 truncate font-medium">{therapyTypes.find(t=>t.id === session.type)?.name || session.type}</p>
                                      <p className="text-xs text-muted truncate">{therapist ? therapist.name : 'Terapis Acak'}</p>
                                  </div>
                             </div>
                             <button onClick={() => handleRemoveSession(index)} className="text-danger/70 hover:text-danger transition text-xs font-semibold ml-2">
                                 Hapus
                             </button>
                          </div>
                        )
                    }) : (
                        <p className="text-center py-4 text-muted text-sm">Belum ada jadwal rutin.</p>
                    )}
                </div>
            </div>
        </div>
        <div className="px-6 py-4 bg-background/50 rounded-b-2xl flex justify-end gap-3">
            <button onClick={onClose} className="px-4 py-2 text-sm font-medium text-muted bg-surface-light rounded-lg hover:bg-surface-light/50 transition">Batal</button>
            <button onClick={handleSave} className="px-4 py-2 text-sm font-medium text-background bg-primary rounded-lg hover:bg-primary-dark transition">Simpan Perubahan</button>
        </div>
      </div>
    </div>
  );
};


const ChildManagementPage: React.FC<ChildManagementPageProps> = ({ children, onAddChild, onAddMultipleChildren, onUpdateChild, onDeleteChild, onAddDailySession, therapyTypes, therapyTimes, daysOfWeek, therapists, userRole }) => {
  const [newName, setNewName] = useState('');
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editingChild, setEditingChild] = useState<MasterChild | null>(null);
  const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
  const [isDailySessionModalOpen, setIsDailySessionModalOpen] = useState(false);
  const [childForDailySession, setChildForDailySession] = useState<MasterChild | null>(null);

  const [activeViewTab, setActiveViewTab] = useState<'Aktif' | 'Non-Aktif'>('Aktif');
  const [deactivatingChild, setDeactivatingChild] = useState<MasterChild | null>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newName.trim()) {
      onAddChild(newName.trim());
      setNewName('');
    }
  };

  const handleOpenEditModal = (child: MasterChild) => {
    setEditingChild(child);
    setIsEditModalOpen(true);
  };

  const handleCloseEditModal = () => {
    setEditingChild(null);
    setIsEditModalOpen(false);
  };

  const handleSaveEdit = (updates: Partial<Omit<MasterChild, 'id'>>) => {
    if (editingChild) {
      onUpdateChild(editingChild.id, updates);
    }
    handleCloseEditModal();
  };

  const handleDeleteClick = (childId: string, childName: string) => {
    if (window.confirm(`Apakah Anda yakin ingin menghapus data siswa "${childName}"? Tindakan ini tidak dapat diurungkan.`)) {
        onDeleteChild(childId);
    }
  }

  const handleDeactivate = (reason: string) => {
    if (deactivatingChild) {
        onUpdateChild(deactivatingChild.id, { status: 'Non-Aktif', inactivityReason: reason });
        setDeactivatingChild(null);
    }
  };

  const handleReactivate = (child: MasterChild) => {
    if (window.confirm(`Aktifkan kembali siswa "${child.name}"?`)) {
        onUpdateChild(child.id, { status: 'Aktif', inactivityReason: undefined });
    }
  };

  const handleOpenDailySessionModal = (child: MasterChild) => {
    setChildForDailySession(child);
    setIsDailySessionModalOpen(true);
  };

  const handleCloseDailySessionModal = () => {
    setChildForDailySession(null);
    setIsDailySessionModalOpen(false);
  };

  const handleSaveDailySession = (session: Omit<TherapySession, 'id' | 'status'>, date: string) => {
    if (childForDailySession) {
      onAddDailySession(childForDailySession.id, session, date);
    }
  };

  const visibleChildren = useMemo(() => {
    return children.filter(c => (c.status || 'Aktif') === activeViewTab);
  }, [children, activeViewTab]);


  return (
    <main className="p-8">
      <EditChildModal 
        isOpen={isEditModalOpen}
        child={editingChild}
        onClose={handleCloseEditModal}
        onSave={handleSaveEdit}
        therapyTypes={therapyTypes}
        therapyTimes={therapyTimes}
        daysOfWeek={daysOfWeek}
        therapists={therapists}
      />
      <UploadChildDataModal
            isOpen={isUploadModalOpen}
            onClose={() => setIsUploadModalOpen(false)}
            onSave={onAddMultipleChildren}
      />
       <AddDailySessionModal 
        isOpen={isDailySessionModalOpen}
        onClose={handleCloseDailySessionModal}
        onSave={handleSaveDailySession}
        child={childForDailySession}
        therapyTypes={therapyTypes}
        therapyTimes={therapyTimes}
        therapists={therapists}
      />
      <DeactivateModal 
        isOpen={!!deactivatingChild}
        onClose={() => setDeactivatingChild(null)}
        onConfirm={handleDeactivate}
        child={deactivatingChild}
      />
      <div className="max-w-6xl mx-auto">
        <h1 className="text-2xl font-bold text-white mb-6">Manajemen Anak</h1>

        <div className="flex gap-4 mb-6">
            <button 
                onClick={() => setActiveViewTab('Aktif')}
                className={`px-4 py-2 rounded-lg font-medium transition ${activeViewTab === 'Aktif' ? 'bg-primary text-background' : 'bg-surface text-muted hover:text-white border border-surface-light'}`}
            >
                Siswa Aktif
            </button>
            <button 
                onClick={() => setActiveViewTab('Non-Aktif')}
                className={`px-4 py-2 rounded-lg font-medium transition ${activeViewTab === 'Non-Aktif' ? 'bg-danger text-white' : 'bg-surface text-muted hover:text-white border border-surface-light'}`}
            >
                Siswa Non-Aktif
            </button>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">

          {userRole === 'admin' && activeViewTab === 'Aktif' && (
            <div className="lg:col-span-1 bg-surface border border-surface-light rounded-2xl p-6 sticky top-28">
              <h2 className="text-lg font-semibold text-white mb-4">Tambah Siswa Baru</h2>
              <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                  <label htmlFor="child-name" className="block mb-2 text-sm font-medium text-muted">Nama Lengkap</label>
                  <input
                    type="text"
                    id="child-name"
                    value={newName}
                    onChange={(e) => setNewName(e.target.value)}
                    className="bg-surface-light border border-surface-light/50 text-white placeholder-muted text-sm rounded-lg focus:ring-primary focus:border-primary block w-full p-2.5 transition"
                    placeholder="Contoh: Budi Santoso"
                    required
                  />
                </div>
                <button
                  type="submit"
                  className="w-full bg-primary hover:bg-primary-dark text-background font-bold py-2.5 px-4 rounded-lg transition-transform duration-200 hover:scale-105"
                >
                  Simpan Siswa
                </button>
              </form>
              <div className="relative my-4">
                  <div className="absolute inset-0 flex items-center" aria-hidden="true">
                      <div className="w-full border-t border-surface-light/50"></div>
                  </div>
                  <div className="relative flex justify-center">
                      <span className="bg-surface px-2 text-sm text-muted">atau</span>
                  </div>
              </div>
              <button
                  type="button"
                  onClick={() => setIsUploadModalOpen(true)}
                  className="w-full bg-secondary hover:bg-secondary/80 text-white font-bold py-2.5 px-4 rounded-lg transition flex items-center justify-center gap-2"
                >
                  <UploadIcon className="w-5 h-5" />
                  Upload Data Siswa
                </button>
            </div>
          )}

          <div className={(userRole === 'admin' && activeViewTab === 'Aktif') ? "lg:col-span-2" : "lg:col-span-3"}>
            <div className="bg-surface border border-surface-light rounded-2xl shadow-lg overflow-hidden">
                <div className="p-6 border-b border-surface-light">
                <h2 className="text-lg font-semibold text-white">
                    {activeViewTab === 'Aktif' ? 'Daftar Siswa Aktif' : 'Arsip Siswa Tidak Aktif'} ({visibleChildren.length})
                </h2>
                </div>
                <div className="overflow-x-auto">
                    <table className="min-w-full divide-y divide-surface-light">
                        <thead className="bg-background/50">
                            <tr>
                                <th scope="col" className="px-6 py-4 text-left text-xs font-medium text-muted uppercase tracking-wider">Nama</th>
                                {activeViewTab === 'Aktif' ? (
                                    <th scope="col" className="px-6 py-4 text-left text-xs font-medium text-muted uppercase tracking-wider">Sesi Rutin</th>
                                ) : (
                                    <th scope="col" className="px-6 py-4 text-left text-xs font-medium text-muted uppercase tracking-wider">Alasan Tidak Aktif</th>
                                )}
                                {userRole === 'admin' && (
                                <th scope="col" className="px-6 py-4 text-center text-xs font-medium text-muted uppercase tracking-wider">Aksi</th>
                                )}
                            </tr>
                        </thead>
                        <tbody className="bg-surface divide-y divide-surface-light">
                            {visibleChildren.length > 0 ? visibleChildren.slice().sort((a,b) => a.name.localeCompare(b.name)).map((child) => (
                                <tr key={child.id} className={`${activeViewTab === 'Non-Aktif' ? 'opacity-70' : ''} hover:bg-surface-light/50 transition-colors`}>
                                    <td className="px-6 py-4 whitespace-nowrap">
                                        <div className="flex items-center">
                                            <div className="flex-shrink-0 h-10 w-10">
                                                <img className={`h-10 w-10 rounded-full object-cover ring-2 ${activeViewTab === 'Non-Aktif' ? 'grayscale' : 'ring-surface-light'}`} src={child.photoUrl} alt={child.name} />
                                            </div>
                                            <div className="ml-4">
                                                <div className="text-sm font-medium text-white">{child.name}</div>
                                                <div className="text-xs text-muted font-mono">{child.id}</div>
                                            </div>
                                        </div>
                                    </td>
                                    {activeViewTab === 'Aktif' ? (
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-muted">
                                            {child.recurringSessions?.length || 0} sesi
                                        </td>
                                    ) : (
                                        <td className="px-6 py-4 text-sm text-danger/80 italic font-medium">
                                            {child.inactivityReason || 'Tidak ada alasan tercatat'}
                                        </td>
                                    )}

                                    {userRole === 'admin' && (
                                    <td className="px-6 py-4 whitespace-nowrap text-center text-sm font-medium">
                                        <div className="flex justify-center items-center gap-2">
                                            {activeViewTab === 'Aktif' ? (
                                                <>
                                                    <button onClick={() => handleOpenDailySessionModal(child)} className="bg-secondary/10 text-secondary hover:bg-secondary/20 transition-colors px-3 py-1 rounded-md text-xs" title="Tambah Sesi Harian">+ Sesi Harian</button>
                                                    <button onClick={() => handleOpenEditModal(child)} className="bg-primary/10 text-primary hover:bg-primary/20 transition-colors px-3 py-1 rounded-md">Edit</button>
                                                    <button onClick={() => setDeactivatingChild(child)} className="bg-warning/10 text-warning hover:bg-warning/20 transition-colors p-1 rounded-md" title="Nonaktifkan Siswa">
                                                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 8h14M5 8a2 2 0 110-4h14a2 2 0 110 4M5 8v10a2 2 0 002 2h10a2 2 0 002-2V8m-9 4h4" /></svg>
                                                    </button>
                                                    <button onClick={() => handleDeleteClick(child.id, child.name)} className="bg-danger/10 text-danger hover:bg-danger/20 transition-colors p-1 rounded-md">
                                                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                                    </button>
                                                </>
                                            ) : (
                                                <>
                                                    <button onClick={() => handleReactivate(child)} className="bg-success/10 text-success hover:bg-success/20 transition-colors px-3 py-1 rounded-md text-xs">Aktifkan Kembali</button>
                                                    <button onClick={() => handleDeleteClick(child.id, child.name)} className="bg-danger/10 text-danger hover:bg-danger/20 transition-colors p-1 rounded-md">
                                                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                                    </button>
                                                </>
                                            )}
                                        </div>
                                    </td>
                                    )}
                                </tr>
                            )) : (
                                <tr>
                                    <td colSpan={userRole === 'admin' ? 3 : 2} className="text-center py-10 text-muted">
                                        {activeViewTab === 'Aktif' ? 'Belum ada data siswa.' : 'Tidak ada arsip siswa non-aktif.'}
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
          </div>

        </div>
      </div>
    </main>
  );
};

