import React from 'react';
import { View, UserRole, MenuItem } from '../types';

interface ReportsHubPageProps {
  userRole: UserRole;
  onNavigate: (view: View) => void;
  menuConfig: MenuItem[];
}

const ReportsHubPage: React.FC<ReportsHubPageProps> = ({ userRole, onNavigate, menuConfig }) => {
  // Define which IDs are considered "Reports" for the hub
  const reportViewIds: View[] = [
    'laporanPerkembangan',
    'laporanAssesment',
    'balancedScorecard',
    'strategicPlan',
    'laporanKeuangan',
    'laporanPemasukan',
    'rekapKehadiran',
    'tinjauanMingguan'
  ];

  // Filter based on user role permissions (logic matches Sidebar.tsx)
  const availableReports = menuConfig.filter(item => {
    if (!reportViewIds.includes(item.id)) return false;

    if (userRole === 'admin') return true;
    if (userRole === 'terapis') {
      const therapistViews: View[] = ['laporanPerkembangan', 'laporanAssesment', 'rekapKehadiran', 'tinjauanMingguan'];
      return therapistViews.includes(item.id);
    }
    if (userRole === 'siswa') {
      const studentViews: View[] = ['laporanPerkembangan', 'laporanAssesment', 'rekapKehadiran'];
      return studentViews.includes(item.id);
    }
    return false;
  });

  const getReportDescription = (id: View) => {
    switch (id) {
      case 'laporanPerkembangan': return 'Laporan berkala hasil terapi yang diunggah ke Google Sites.';
      case 'laporanAssesment': return 'Dokumen evaluasi mendalam Terapi Okupasi dan Terapi Wicara.';
      case 'balancedScorecard': return 'Monitoring kinerja organisasi dari 4 perspektif strategis.';
      case 'strategicPlan': return 'Rencana kerja tahunan dan tracking pencapaian program.';
      case 'laporanKeuangan': return 'Ringkasan pemasukan dan pengeluaran operasional yayasan.';
      case 'laporanPemasukan': return 'Analisis detail pendapatan dari sesi terapi siswa.';
      case 'rekapKehadiran': return 'Data historis kehadiran siswa dalam bentuk kalender.';
      case 'tinjauanMingguan': return 'Visualisasi data grafik jumlah siswa per jenis terapi.';
      default: return 'Akses dokumen laporan departemen terkait.';
    }
  };

  return (
    <main className="p-8">
      <div className="max-w-6xl mx-auto">
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-white">Pusat Laporan</h1>
          <p className="text-muted mt-2 text-lg">Akses cepat ke seluruh sistem pelaporan Pelangi Lazuardi.</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {availableReports.map((report) => (
            <button
              key={report.id}
              onClick={() => onNavigate(report.id)}
              className="group relative bg-surface border border-surface-light rounded-2xl p-6 text-left transition-all duration-300 hover:scale-[1.02] hover:bg-surface-light/50 hover:shadow-2xl hover:shadow-primary/10 overflow-hidden"
            >
              <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                <report.Icon className="w-24 h-24 rotate-12" />
              </div>

              <div className="relative z-10">
                <div className="w-12 h-12 rounded-xl bg-primary/10 text-primary flex items-center justify-center mb-4 group-hover:bg-primary group-hover:text-background transition-colors duration-300">
                  <report.Icon className="w-6 h-6" />
                </div>
                <h3 className="text-xl font-bold text-white mb-2 group-hover:text-primary transition-colors">{report.label}</h3>
                <p className="text-sm text-muted line-clamp-2 mb-4">{getReportDescription(report.id)}</p>

                <div className="flex items-center text-primary text-sm font-semibold group-hover:translate-x-2 transition-transform duration-300">
                  Buka Laporan
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 ml-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" />
                  </svg>
                </div>
              </div>
            </button>
          ))}
        </div>

        {availableReports.length === 0 && (
          <div className="bg-surface border border-surface-light rounded-2xl p-12 text-center">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 text-muted mx-auto mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.172 9.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            <p className="text-muted text-lg">Anda tidak memiliki akses ke laporan saat ini.</p>
          </div>
        )}
      </div>
    </main>
  );
};

