const academicMonths = ['Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember', 'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni'];

const generateFinancialData = (): { [key: string]: FinancialRecord[] } => {
    const data: { [key: string]: FinancialRecord[] } = {};
    const academicYears: AcademicYear[] = [
        { id: '2023-2024', label: '2023/2024' },
        { id: '2024-2025', label: '2024/2025' },
        { id: '2025-2026', label: '2025/2026' },
    ];

    academicYears.forEach(year => {
        data[year.id] = academicMonths.map(month => {
            const income = Math.floor(Math.random() * (80000000 - 40000000 + 1)) + 40000000;

            const expenseDetails: ExpenseDetail[] = [];
            let totalExpense = 0;

            // Gaji Terapis
            const gaji = Math.floor(Math.random() * (25000000 - 15000000 + 1)) + 15000000;
            expenseDetails.push({ id: `exp-gaji-${month}`, category: "Gaji Terapis", description: `Gaji bulan ${month}`, amount: gaji });
            totalExpense += gaji;

            // Operasional
            const operasional = Math.floor(Math.random() * (5000000 - 2000000 + 1)) + 2000000;
            expenseDetails.push({ id: `exp-op-${month}`, category: "Biaya Operasional", description: "ATK, kebersihan, dll.", amount: operasional });
            totalExpense += operasional;

            // Pembelian APE
            if (Math.random() > 0.5) {
                const ape = Math.floor(Math.random() * (3000000 - 500000 + 1)) + 500000;
                expenseDetails.push({ id: `exp-ape-${month}`, category: "Pembelian APE", description: "Pembelian alat permainan edukatif baru", amount: ape });
                totalExpense += ape;
            }

            return {
                month,
                income,
                expense: totalExpense,
                expenseDetails,
            };
        });
    });
    return data;
};

