          initialData[year.id] = Array.from({ length: 12 }, (_, i) => {
              const monthIndex = (startMonth + i) % 12;
              const currentYear = startYear + Math.floor((startMonth + i) / 12);

              let monthlyIncome = 0;
              const daysInMonth = new Date(currentYear, monthIndex + 1, 0).getDate();

