    if (userRole === 'siswa') {
        return fullDaySchedule.filter(c => c.id === loggedInUserId);
    }
    if (userRole === 'terapis') {
        return fullDaySchedule
            .map(child => ({
                ...child,
                sessions: child.sessions.filter(s => s.therapistId === loggedInUserId),
