                    return finRecord;
                });
            }
            return newFinData;
        });

        return newData;
    });
  };

  const handleUpdateAssessmentStatus = useCallback((childId: string, newStatus: AssessmentStatus) => {
    setAllChildren(prevChildren => 
        prevChildren.map(child => 
            child.id === childId ? { ...child, assessmentStatus: newStatus } : child
        )
    );
  }, []);

  const handleAddAssessmentReport = useCallback((report: Omit<AssessmentReport, 'id'>) => {
    const newReport: AssessmentReport = {
        ...report,
        id: `AR${Date.now()}`,
    };
    setAssessmentReports(prev => [...prev, newReport]);
  }, []);

  const handleUpdateAssessmentReport = useCallback((updatedReport: AssessmentReport) => {
      setAssessmentReports(prev => prev.map(r => r.id === updatedReport.id ? updatedReport : r));
  }, []);

  const handleDeleteAssessmentReport = useCallback((reportId: string) => {
      setAssessmentReports(prev => prev.filter(r => r.id !== reportId));
  }, []);

  const handleUpdateAdminProfile = (newProfile: { name: string; email: string; photoUrl: string }) => {
    setAdminProfile(newProfile);
    setIsProfileModalOpen(false);
  };

  const handleAddAcademicYear = (newYearLabel: string) => {
      const parts = newYearLabel.split('/');
      if (parts.length !== 2) return;

      const startYear = parseInt(parts[0]);
      const endYear = parseInt(parts[1]);

      if(isNaN(startYear) || isNaN(endYear)) return;

      const id = `${startYear}-${endYear}`;

      setAcademicYears(prev => [...prev, { id, label: newYearLabel }]);

      // Init Financial Data for new year
       setFinancialData(prevData => ({
          ...prevData,
          [id]: academicMonths.map(month => ({
              month,
              income: 0,
              expense: 0,
              expenseDetails: []
          }))
      }));

      // Init Income Data for new year
       setIncomeReportData(prevData => ({
          ...prevData,
          [id]: academicMonths.map(month => ({
              month,
              income: 0,
              incomeDetails: []
          }))
      }));
  };


  const filteredData = useMemo(() => dataForSelectedDate.filter(child => child.name.toLowerCase().includes(searchTerm.toLowerCase())), [dataForSelectedDate, searchTerm]);

  const todayDate = currentTime.toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
  const todayTime = currentTime.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' });

  const sessionToEdit = useMemo(() => {
    if (!editingSession) return null;
    const child = dataForSelectedDate.find(c => c.id === editingSession.childId);
    return child?.sessions.find(s => s.id === editingSession.sessionId) ?? null;
  }, [editingSession, dataForSelectedDate]);

  const childNameForModal = useMemo(() => (editingSession ? dataForSelectedDate.find(c => c.id === editingSession.childId)?.name ?? '' : ''), [editingSession, dataForSelectedDate]);

  const visibleSidebarMenu = useMemo(() => {
    return isEditing ? draftSidebarConfig : sidebarMenuConfig;
  }, [isEditing, draftSidebarConfig, sidebarMenuConfig]);

  const renderContent = () => {
    if (isLoading) return <div className="flex justify-center items-center h-full"><p className="text-lg text-text-muted">Memuat data...</p></div>;

    switch (activeView) {
      case 'manajemenAnak': return <ChildManagementPage children={allChildren} onAddChild={handleAddChild} onAddMultipleChildren={handleAddMultipleChildren} onUpdateChild={handleUpdateChild} onDeleteChild={handleDeleteChild} onAddDailySession={handleAddDailySession} therapyTypes={therapyTypes} therapyTimes={times} daysOfWeek={daysOfWeek} therapists={allTherapists} userRole={userRole} />;
      case 'manajemenPengguna': return <UserManagementPage children={allChildren} onUpdateChild={handleUpdateChild} therapists={allTherapists} onUpdateTherapist={handleUpdateTherapist} userRole={userRole}/>;
      case 'assesmentAnak': return <AssessmentPage allChildren={visibleChildren} onUpdateStatus={handleUpdateAssessmentStatus} />;
      case 'manajemenTerapis': return <TherapistManagementPage therapists={allTherapists} onAddTherapist={handleAddTherapist} onUpdateTherapist={handleUpdateTherapist} onDeleteTherapist={handleDeleteTherapist} therapyTypes={therapyTypes} userRole={userRole}/>;
      case 'pusatLaporan': return <ReportsHubPage userRole={userRole} onNavigate={setActiveView} menuConfig={sidebarMenuConfig} />;
      case 'laporanPerkembangan': return <ReportsPage />;
      case 'laporanAssesment': return <AssessmentReportPage reports={visibleAssessmentReports} children={visibleChildren} therapists={allTherapists} onAddReport={handleAddAssessmentReport} onUpdateReport={handleUpdateAssessmentReport} onDeleteReport={handleDeleteAssessmentReport} logoUrl={logoUrl} therapyTypes={therapyTypes} userRole={userRole} />;
      case 'balancedScorecard': return <BalancedScorecardPage financialData={Object.values(financialData).flat()} allChildren={allChildren} allTherapists={allTherapists} />;
      case 'strategicPlan': return <StrategicPlanPage data={strategicPlans} onUpdate={setStrategicPlans} logoUrl={logoUrl} />;
      case 'laporanKeuangan': return <FinancialReportPage allData={financialData} academicYears={academicYears} onUpdateData={handleUpdateFinancialData} onAddAcademicYear={handleAddAcademicYear} logoUrl={logoUrl} />;
      case 'laporanPemasukan': return <IncomeReportPage allIncomeData={incomeReportData} onUpdateData={handleUpdateIncomeData} academicYears={academicYears} therapyTypes={therapyTypes} therapyCosts={therapyCosts} />;
      case 'tagihan': return <BillingPage allChildren={visibleChildren} therapyTypes={therapyTypes} logoUrl={logoUrl} onNavigate={setActiveView} userRole={userRole} onUpdatePaymentStatus={handleUpdatePaymentStatus} therapyCosts={therapyCosts} onUpdateCost={setTherapyCosts} />;
      case 'rekapKehadiran': return <AttendanceRecapPage allChildren={visibleChildren} attendanceRecords={attendanceRecords} />;
      case 'pengaturan': return <SettingsPage therapyTypes={therapyTypes} onAddTherapyType={handleAddTherapyType} onDeleteTherapyType={handleDeleteTherapyType} themes={themes} activeTheme={activeTheme} onThemeChange={setActiveTheme} gradientSettings={gradientSettings} onGradientChange={setGradientSettings} logoUrl={logoUrl} onLogoChange={setLogoUrl} />;
      case 'tinjauanMingguan':
        return (
          <main className="p-8">
            <div className="max-w-6xl mx-auto">
              <h1 className="text-2xl font-bold text-text-heading mb-6">Tinjauan Mingguan</h1>
              <WeeklyOverviewChart data={weeklyData} therapyTypes={therapyTypes} />
            </div>
          </main>
        );
      case 'dashboard': default:
        return (
          <main className="flex-1 p-8">
             <div className="flex justify-between items-center mb-8">
                <div>
                  <h2 className="text-2xl font-bold text-text-heading">Selamat Datang, {loggedInUser.name}</h2>
                  <p className="text-text-muted">Ringkasan aktivitas terapi.</p>
                </div>
                <div className="text-right hidden sm:block">
                  <p className="text-lg font-bold text-text-heading font-mono">{todayTime}</p>
                  <p className="text-sm text-text-muted">{todayDate}</p>
                </div>
             </div>

             <div className="mb-8">
                <DashboardStats 
                    data={dataForSelectedDate} 
                    totalRegisteredChildren={visibleChildren.filter(c => c.status !== 'Non-Aktif').length} 
                    projectedMonthlySessions={projectedMonthlySessions}
                    scheduledToday={scheduledTodayCount}
                    onCardClick={handleStatCardClick} 
                    selectedDate={selectedDate}
                />
            </div>

            <div className="bg-surface border border-surface-light rounded-2xl p-6">
                <div className="flex justify-between items-center mb-4 flex-wrap gap-4">
                  <div>
                    <h3 className="text-xl font-bold text-text-heading">Jadwal Terapi</h3>
                    <p className="text-text-muted text-sm mt-1">
                      Menampilkan jadwal untuk <span className="font-semibold text-primary">{selectedDate.toLocaleDateString('id-ID', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</span>.
                    </p>
                  </div>
                  <div className="flex items-center gap-4">
                     <input 
                        type="date"
                        value={selectedDate.toISOString().split('T')[0]}
                        onChange={e => {
                            // This handles timezone issues where new Date('YYYY-MM-DD') might be off by a day.
                            const date = new Date(e.target.value);
                            const userTimezoneOffset = date.getTimezoneOffset() * 60000;
                            setSelectedDate(new Date(date.getTime() + userTimezoneOffset));
                        }}
                        className="bg-surface-light border border-surface-light/50 text-white placeholder-muted text-sm rounded-lg focus:ring-primary focus:border-primary block p-2.5 transition"
                    />
                    <div className="relative"><input type="text" placeholder="Cari nama anak..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="bg-surface-light border border-surface-light/50 text-text-base placeholder-text-muted text-sm rounded-lg focus:ring-primary focus:border-primary block w-64 pl-10 p-2.5 transition"/><div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none"><svg className="w-5 h-5 text-text-muted" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg></div></div>
                  </div>
                </div>
                <AttendanceTable
                  data={filteredData}
                  onStatusChange={handleStatusChange}
                  onEditSession={handleOpenEditSessionModal}
                  therapyTypes={therapyTypes}
                  therapists={allTherapists}
                  userRole={userRole}
                />
            </div>
          </main>
        );
    }
  };

  if (!isAuthenticated) {
    return <LoginPage 
      onLoginSuccess={handleLoginSuccess}
      logoUrl={logoUrl}
      allChildren={allChildren}
      allTherapists={allTherapists}
      onLogoChange={setLogoUrl}
    />;
  }

  return (
    <div className="bg-background text-text-base min-h-screen flex transition-colors duration-300">
      <Sidebar 
        userRole={userRole}
        menuConfig={visibleSidebarMenu}
        activeView={activeView}
        onNavigate={setActiveView}
        logoUrl={logoUrl} 
        isEditing={isEditing}
        onToggleEdit={handleEditToggle}
        onSave={handleSaveMenus}
        onCancel={handleCancelEdit}
        draftConfig={draftSidebarConfig}
        onDraftChange={setDraftSidebarConfig}
      />
      <div className="flex-1 flex flex-col max-h-screen">
        <header className="bg-background/70 backdrop-blur-lg border-b border-surface-light sticky top-0 z-10 px-8 py-4 flex justify-between items-center flex-shrink-0">
          <div className="flex items-center gap-4">
            <img src={logoUrl} alt="Logo Pelangi Lazuardi" className="h-10 w-auto" />
            <div>
              <h1 className="text-xl font-bold text-text-heading">Pelangi Lazuardi</h1>
              <p className="text-sm text-text-muted">Sistem Manajemen Terapi</p>
            </div>
          </div>
          <nav className="hidden md:flex items-center gap-4 text-sm font-medium">
            {(isEditing ? draftHeaderConfig : headerMenuConfig).map((item, index) =>
              isEditing ? (
                  <div key={item.id} className="flex flex-col gap-1">
                      <input
                          type="text"
                          value={item.label}
                          onChange={(e) => {
                              const newConfig = [...draftHeaderConfig];
                              newConfig[index] = { ...newConfig[index], label: e.target.value };
                              setDraftHeaderConfig(newConfig);
                          }}
                          className="bg-surface-light border border-surface-light/50 text-white text-xs rounded px-2 py-1 focus:ring-primary focus:border-primary w-32"
                      />
                  </div>
              ) : (
                <a
                  key={item.id}
                  href={item.href}
                  target={item.isExternal ? "_blank" : undefined}
                  rel={item.isExternal ? "noopener noreferrer" : undefined}
                  className="text-text-muted hover:text-primary transition-colors"
                >
                  {item.label}
                </a>
              )
            )}
          </nav>
          <div className="flex items-center gap-4">
             <button className="relative p-2 text-text-muted hover:text-white transition-colors">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9" /></svg>
                <span className="absolute top-1 right-1 h-2.5 w-2.5 bg-danger rounded-full ring-2 ring-background"></span>
             </button>
             <button onClick={() => setIsProfileModalOpen(true)} className="flex items-center gap-3 pl-4 border-l border-surface-light group">
                <div className="text-right hidden sm:block">
                    <p className="text-sm font-medium text-text-heading group-hover:text-primary transition-colors">{loggedInUser.name}</p>
                    <p className="text-xs text-text-muted">{userRole ? userRole.charAt(0).toUpperCase() + userRole.slice(1) : 'Guest'}</p>
                </div>
                <img src={loggedInUser.photoUrl || 'https://i.pravatar.cc/100?u=user'} alt="User" className="h-9 w-9 rounded-full object-cover ring-2 ring-surface-light group-hover:ring-primary transition-all" />
             </button>
             <button onClick={handleLogout} className="text-muted hover:text-danger transition-colors p-2" title="Keluar">
                 <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
             </button>
          </div>
        </header>
        <div className="flex-1 overflow-auto bg-background/50 backdrop-blur-sm">
            {renderContent()}
        </div>
      </div>

      <EditSessionModal 
        isOpen={!!editingSession} 
        session={sessionToEdit} 
        childName={childNameForModal}
        onClose={handleCloseEditSessionModal}
        onSave={(updates) => {
            if (editingSession) {
               handleUpdateSession(editingSession.childId, editingSession.sessionId, updates);
            }
        }}
        onDelete={() => {
            if (editingSession) {
                handleDeleteSession(editingSession.childId, editingSession.sessionId);
            }
        }}
        therapyTypes={therapyTypes}
        therapyTimes={times}
      />
      <DetailsModal 
        isOpen={detailsModalData.isOpen}
        onClose={() => setDetailsModalData({ ...detailsModalData, isOpen: false })}
        title={detailsModalData.title}
        list={detailsModalData.list}
      />
      <ProfileModal
        isOpen={isProfileModalOpen}
        onClose={() => setIsProfileModalOpen(false)}
        currentProfile={adminProfile}
        onSave={handleUpdateAdminProfile}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { View, MenuItem, UserRole } from '../types';
import EditMenuIcon from './icons/EditMenuIcon';
import DragHandleIcon from './icons/DragHandleIcon';

const SettingsIcon: React.FC<{className?: string}> = ({className}) => <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.096 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>;

const MenuToggleIcon: React.FC<{className?: string}> = ({className}) => (
  <svg xmlns="http://www.w3.org/2000/svg" className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
  </svg>
);

const ChevronLeftIcon: React.FC<{className?: string}> = ({className}) => (
    <svg xmlns="http://www.w3.org/2000/svg" className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
    </svg>
);

interface SidebarProps {
  userRole: UserRole;
  menuConfig: MenuItem[];
  activeView: View;
  onNavigate: (view: View) => void;
  logoUrl: string;
  // New props for global edit mode
  isEditing: boolean;
  onToggleEdit: () => void;
  onSave: () => void;
  onCancel: () => void;
  draftConfig: MenuItem[];
  onDraftChange: (newConfig: MenuItem[]) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ 
    userRole,
    menuConfig, 
    activeView, 
    onNavigate, 
    logoUrl,
    isEditing,
    onToggleEdit,
    onSave,
    onCancel,
    draftConfig,
    onDraftChange
}) => {
  const [renamingId, setRenamingId] = useState<View | null>(null);
  const [draggedItemIndex, setDraggedItemIndex] = useState<number | null>(null);
  // Default to collapsed (true) so text is hidden initially
  const [isCollapsed, setIsCollapsed] = useState(true);

  const renameInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (renamingId && renameInputRef.current) {
        renameInputRef.current.focus();
    }
  }, [renamingId]);

  // Force expand when editing
  useEffect(() => {
      if (isEditing) {
          setIsCollapsed(false);
      }
  }, [isEditing]);

  const handleRename = (id: View, newLabel: string) => {
    onDraftChange(draftConfig.map(item => item.id === id ? { ...item, label: newLabel } : item));
  };

  const finishRenaming = () => {
      setRenamingId(null);
  }

  // Drag and Drop Handlers
  const handleDragStart = (e: React.DragEvent<HTMLElement>, index: number) => {
    setDraggedItemIndex(index);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent<HTMLElement>, index: number) => {
    e.preventDefault();
    if (draggedItemIndex === null || draggedItemIndex === index) return;

    const newConfig = [...draftConfig];
    const [draggedItem] = newConfig.splice(draggedItemIndex, 1);
    newConfig.splice(index, 0, draggedItem);

    setDraggedItemIndex(index);
    onDraftChange(newConfig);
  };

  const handleDragEnd = () => {
    setDraggedItemIndex(null);
  };

  let lastGroup = 0;

  const currentMenu = isEditing ? draftConfig : menuConfig;

  const visibleMenu = useMemo(() => {
    if (userRole === 'admin') {
      return currentMenu;
    }
    if (userRole === 'terapis') {
        const therapistViews: View[] = ['dashboard', 'assesmentAnak', 'pusatLaporan', 'laporanPerkembangan', 'laporanAssesment', 'rekapKehadiran'];
        return currentMenu.filter(item => therapistViews.includes(item.id));
    }
    const nonAdminViews: View[] = ['dashboard', 'assesmentAnak', 'pusatLaporan', 'laporanPerkembangan', 'laporanAssesment', 'tagihan', 'rekapKehadiran'];
    return currentMenu.filter(item => nonAdminViews.includes(item.id));
  }, [currentMenu, userRole]);

  return (
    <aside 
        className={`flex-shrink-0 bg-surface/30 border-r border-surface-light flex flex-col p-4 transition-all duration-300 ease-in-out ${isCollapsed ? 'w-20' : 'w-64'}`}
        onMouseEnter={() => !isEditing && setIsCollapsed(false)}
        onMouseLeave={() => !isEditing && setIsCollapsed(true)}
    >
      <div className="flex justify-end mb-2">
          <button 
            onClick={() => !isEditing && setIsCollapsed(!isCollapsed)} 
            className={`p-1.5 rounded-lg text-muted hover:bg-surface hover:text-white transition-colors ${isEditing ? 'opacity-50 cursor-not-allowed' : ''}`}
            title={isCollapsed ? "Expand Menu" : "Collapse Menu"}
          >
              {isCollapsed ? <MenuToggleIcon className="w-5 h-5" /> : <ChevronLeftIcon className="w-5 h-5" />}
          </button>
      </div>

      <div className={`flex items-center justify-center mb-4 transition-all duration-300 ${isCollapsed ? 'h-16 px-0' : 'h-32 px-4'}`}>
        <button onClick={() => onNavigate('dashboard')} className="transition-opacity duration-200 hover:opacity-80 focus:outline-none focus:ring-2 focus:ring-primary rounded-lg">
          <img src={logoUrl} alt="Logo Pelangi Lazuardi" className={`w-auto transition-all duration-300 ${isCollapsed ? 'h-10' : 'h-24'}`} />
        </button>
      </div>

      <nav className="flex-1 space-y-1 overflow-x-hidden">
        {visibleMenu.map((item, index) => {
          const showDivider = item.group !== lastGroup && index > 0 && item.group !== 1; 
          lastGroup = item.group;
          const isRenaming = renamingId === item.id;
          const isActive = activeView === item.id;

          return (
            <React.Fragment key={item.id}>
              {showDivider && <div className="pt-2 mt-2 border-t border-surface-light" />}
              <div
                draggable={isEditing}
                onDragStart={(e) => handleDragStart(e, index)}
                onDragOver={(e) => handleDragOver(e, index)}
                onDragEnd={handleDragEnd}
                className={`flex items-center rounded-lg transition-colors duration-200 ${draggedItemIndex === index ? 'opacity-50' : ''} ${isEditing ? 'cursor-move' : ''}`}
              >
                {isEditing && <DragHandleIcon className="w-5 h-5 mr-2 text-muted flex-shrink-0" />}
                <button
                  onClick={() => !isEditing && onNavigate(item.id)}
                  className={`flex items-center w-full px-4 py-3 text-sm font-medium text-left rounded-lg transition-colors duration-200 group relative ${
                    isActive && !isEditing
                      ? 'bg-primary/10 text-primary'
                      : 'text-muted hover:bg-surface hover:text-white'
                  } ${isCollapsed ? 'justify-center px-2' : ''}`}
                  title={isCollapsed ? item.label : ''}
                >
                  <item.Icon className={`w-5 h-5 flex-shrink-0 ${!isCollapsed ? 'mr-3' : ''}`} />

                  {!isCollapsed && (
                      isRenaming ? (
                        <input
                          ref={renameInputRef}
                          type="text"
                          value={item.label}
                          onChange={(e) => handleRename(item.id, e.target.value)}
                          onBlur={finishRenaming}
                          onKeyDown={(e) => e.key === 'Enter' && finishRenaming()}
                          className="bg-surface-light text-white w-full -m-1 p-1 rounded"
                        />
                      ) : (
                        <span className="flex-1 truncate animate-fade-in-up">{item.label}</span>
                      )
                  )}

                  {isEditing && !isRenaming && !isCollapsed && (
                     <svg onClick={(e) => { e.stopPropagation(); setRenamingId(item.id); }} xmlns="http://www.w3.org/2000/svg" className="w-4 h-4 ml-2 text-muted opacity-0 group-hover:opacity-100 transition-opacity" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.5L16.732 3.732z" /></svg>
                  )}
                </button>
              </div>
            </React.Fragment>
          );
        })}
      </nav>
      {userRole === 'admin' && (
        <div className="mt-auto space-y-2">
          <button 
            onClick={() => onNavigate('pengaturan')} 
            className={`flex items-center w-full px-4 py-3 text-sm font-medium text-left rounded-lg transition-colors duration-200 ${ activeView === 'pengaturan' ? 'bg-primary/10 text-primary' : 'text-muted hover:bg-surface hover:text-white' } ${isCollapsed ? 'justify-center px-2' : ''}`}
            title={isCollapsed ? 'Pengaturan' : ''}
          >
              <SettingsIcon className={`w-5 h-5 flex-shrink-0 ${!isCollapsed ? 'mr-3' : ''}`} />
              {!isCollapsed && <span className="animate-fade-in-up">Pengaturan</span>}
          </button>
          {isEditing ? (
              <div className={`flex items-center gap-2 ${isCollapsed ? 'flex-col' : ''}`}>
                  <button onClick={onCancel} className="w-full text-center px-4 py-2 text-sm font-medium rounded-lg bg-surface-light text-muted hover:bg-surface">{isCollapsed ? 'X' : 'Batal'}</button>
                  <button onClick={onSave} className="w-full text-center px-4 py-2 text-sm font-medium rounded-lg bg-primary text-background hover:bg-primary-dark">{isCollapsed ? '✓' : 'Simpan'}</button>
              </div>
          ) : (
              <button 
                onClick={onToggleEdit} 
                className={`flex items-center w-full px-4 py-3 text-sm font-medium text-left rounded-lg transition-colors duration-200 text-muted hover:bg-surface hover:text-white ${isCollapsed ? 'justify-center px-2' : ''}`}
                title={isCollapsed ? 'Edit Menu' : ''}
              >
                  <EditMenuIcon className={`w-5 h-5 flex-shrink-0 ${!isCollapsed ? 'mr-3' : ''}`} />
                  {!isCollapsed && <span className="animate-fade-in-up">Edit Menu</span>}
              </button>
          )}
        </div>
      )}
    </aside>
  );
};

