interface SidebarProps {
  userRole: UserRole;
  menuConfig: MenuItem[];
  activeView: View;
  onNavigate: (view: View) => void;
  logoUrl: string;
  // New props for global edit mode
  isEditing: boolean;
  onToggleEdit: () => void;
  onSave: () => void;
  onCancel: () => void;
  draftConfig: MenuItem[];
  onDraftChange: (newConfig: MenuItem[]) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ 
    userRole,
    menuConfig, 
    activeView, 
    onNavigate, 
    logoUrl,
    isEditing,
    onToggleEdit,
    onSave,
    onCancel,
    draftConfig,
    onDraftChange
}) => {
  const [renamingId, setRenamingId] = useState<View | null>(null);
  const [draggedItemIndex, setDraggedItemIndex] = useState<number | null>(null);
  // Default to collapsed (true) so text is hidden initially
  const [isCollapsed, setIsCollapsed] = useState(true);

  const renameInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (renamingId && renameInputRef.current) {
        renameInputRef.current.focus();
    }
  }, [renamingId]);

  // Force expand when editing
  useEffect(() => {
      if (isEditing) {
          setIsCollapsed(false);
      }
  }, [isEditing]);

  const handleRename = (id: View, newLabel: string) => {
    onDraftChange(draftConfig.map(item => item.id === id ? { ...item, label: newLabel } : item));
  };

  const finishRenaming = () => {
      setRenamingId(null);
  }

  // Drag and Drop Handlers
  const handleDragStart = (e: React.DragEvent<HTMLElement>, index: number) => {
    setDraggedItemIndex(index);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent<HTMLElement>, index: number) => {
    e.preventDefault();
    if (draggedItemIndex === null || draggedItemIndex === index) return;

    const newConfig = [...draftConfig];
    const [draggedItem] = newConfig.splice(draggedItemIndex, 1);
    newConfig.splice(index, 0, draggedItem);

    setDraggedItemIndex(index);
    onDraftChange(newConfig);
  };

  const handleDragEnd = () => {
    setDraggedItemIndex(null);
  };

  let lastGroup = 0;

  const currentMenu = isEditing ? draftConfig : menuConfig;

  const visibleMenu = useMemo(() => {
    if (userRole === 'admin') {
      return currentMenu;
    }
    if (userRole === 'terapis') {
        // Pusat Laporan removed from therapist view
        const therapistViews: View[] = ['dashboard', 'assesmentAnak', 'laporanPerkembangan', 'laporanAssesment', 'rekapKehadiran'];
        return currentMenu.filter(item => therapistViews.includes(item.id));
    }
    // Pusat Laporan removed from student/other non-admin views
    const nonAdminViews: View[] = ['dashboard', 'assesmentAnak', 'laporanPerkembangan', 'laporanAssesment', 'tagihan', 'rekapKehadiran'];
    return currentMenu.filter(item => nonAdminViews.includes(item.id));
  }, [currentMenu, userRole]);

  return (
    <aside 
        className={`flex-shrink-0 bg-surface/30 border-r border-surface-light flex flex-col p-4 transition-all duration-300 ease-in-out ${isCollapsed ? 'w-20' : 'w-64'}`}
        onMouseEnter={() => !isEditing && setIsCollapsed(false)}
        onMouseLeave={() => !isEditing && setIsCollapsed(true)}
    >
      <div className="flex justify-end mb-2">
          <button 
            onClick={() => !isEditing && setIsCollapsed(!isCollapsed)} 
            className={`p-1.5 rounded-lg text-muted hover:bg-surface hover:text-white transition-colors ${isEditing ? 'opacity-50 cursor-not-allowed' : ''}`}
            title={isCollapsed ? "Expand Menu" : "Collapse Menu"}
          >
              {isCollapsed ? <MenuToggleIcon className="w-5 h-5" /> : <ChevronLeftIcon className="w-5 h-5" />}
          </button>
      </div>

      <div className={`flex items-center justify-center mb-4 transition-all duration-300 ${isCollapsed ? 'h-16 px-0' : 'h-32 px-4'}`}>
        <button onClick={() => onNavigate('dashboard')} className="transition-opacity duration-200 hover:opacity-80 focus:outline-none focus:ring-2 focus:ring-primary rounded-lg">
          <img src={logoUrl} alt="Logo Pelangi Lazuardi" className={`w-auto transition-all duration-300 ${isCollapsed ? 'h-10' : 'h-24'}`} />
        </button>
      </div>

      <nav className="flex-1 space-y-1 overflow-x-hidden">
        {visibleMenu.map((item, index) => {
          const showDivider = item.group !== lastGroup && index > 0 && item.group !== 1; 
          lastGroup = item.group;
          const isRenaming = renamingId === item.id;
          const isActive = activeView === item.id;

          return (
            <React.Fragment key={item.id}>
              {showDivider && <div className="pt-2 mt-2 border-t border-surface-light" />}
              <div
                draggable={isEditing}
                onDragStart={(e) => handleDragStart(e, index)}
                onDragOver={(e) => handleDragOver(e, index)}
                onDragEnd={handleDragEnd}
                className={`flex items-center rounded-lg transition-colors duration-200 ${draggedItemIndex === index ? 'opacity-50' : ''} ${isEditing ? 'cursor-move' : ''}`}
              >
                {isEditing && <DragHandleIcon className="w-5 h-5 mr-2 text-muted flex-shrink-0" />}
                <button
                  onClick={() => !isEditing && onNavigate(item.id)}
                  className={`flex items-center w-full px-4 py-3 text-sm font-medium text-left rounded-lg transition-colors duration-200 group relative ${
                    isActive && !isEditing
                      ? 'bg-primary/10 text-primary'
                      : 'text-muted hover:bg-surface hover:text-white'
                  } ${isCollapsed ? 'justify-center px-2' : ''}`}
                  title={isCollapsed ? item.label : ''}
                >
                  <item.Icon className={`w-5 h-5 flex-shrink-0 ${!isCollapsed ? 'mr-3' : ''}`} />

                  {!isCollapsed && (
                      isRenaming ? (
                        <input
                          ref={renameInputRef}
                          type="text"
                          value={item.label}
                          onChange={(e) => handleRename(item.id, e.target.value)}
                          onBlur={finishRenaming}
                          onKeyDown={(e) => e.key === 'Enter' && finishRenaming()}
                          className="bg-surface-light text-white w-full -m-1 p-1 rounded"
                        />
                      ) : (
                        <span className="flex-1 truncate animate-fade-in-up">{item.label}</span>
                      )
                  )}

                  {isEditing && !isRenaming && !isCollapsed && (
                     <svg onClick={(e) => { e.stopPropagation(); setRenamingId(item.id); }} xmlns="http://www.w3.org/2000/svg" className="w-4 h-4 ml-2 text-muted opacity-0 group-hover:opacity-100 transition-opacity" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.5L16.732 3.732z" /></svg>
                  )}
                </button>
              </div>
            </React.Fragment>
          );
        })}
      </nav>
      {userRole === 'admin' && (
        <div className="mt-auto space-y-2">
          <button 
            onClick={() => onNavigate('pengaturan')} 
            className={`flex items-center w-full px-4 py-3 text-sm font-medium text-left rounded-lg transition-colors duration-200 ${ activeView === 'pengaturan' ? 'bg-primary/10 text-primary' : 'text-muted hover:bg-surface hover:text-white' } ${isCollapsed ? 'justify-center px-2' : ''}`}
            title={isCollapsed ? 'Pengaturan' : ''}
          >
              <SettingsIcon className={`w-5 h-5 flex-shrink-0 ${!isCollapsed ? 'mr-3' : ''}`} />
              {!isCollapsed && <span className="animate-fade-in-up">Pengaturan</span>}
          </button>
          {isEditing ? (
              <div className={`flex items-center gap-2 ${isCollapsed ? 'flex-col' : ''}`}>
                  <button onClick={onCancel} className="w-full text-center px-4 py-2 text-sm font-medium rounded-lg bg-surface-light text-muted hover:bg-surface">{isCollapsed ? 'X' : 'Batal'}</button>
                  <button onClick={onSave} className="w-full text-center px-4 py-2 text-sm font-medium rounded-lg bg-primary text-background hover:bg-primary-dark">{isCollapsed ? '✓' : 'Simpan'}</button>
              </div>
          ) : (
              <button 
                onClick={onToggleEdit} 
                className={`flex items-center w-full px-4 py-3 text-sm font-medium text-left rounded-lg transition-colors duration-200 text-muted hover:bg-surface hover:text-white ${isCollapsed ? 'justify-center px-2' : ''}`}
                title={isCollapsed ? 'Edit Menu' : ''}
              >
                  <EditMenuIcon className={`w-5 h-5 flex-shrink-0 ${!isCollapsed ? 'mr-3' : ''}`} />
                  {!isCollapsed && <span className="animate-fade-in-up">Edit Menu</span>}
              </button>
          )}
        </div>
      )}
    </aside>
  );
};

export default Sidebar;
